    print("[AutoChessMode] 节点数量: " .. tostring(#nodes))
    print("[AutoChessMode] 节点状态详情:")
    for ____, node in ipairs(nodes) do
        print((("[AutoChessMode]   - " .. tostring(node.id)) .. ": ") .. tostring(node.status))
    end
    print("[AutoChessMode] 已完成关卡列表: " .. table.concat(completedArray, ", "))
