    if not loadedPieces or #loadedPieces == 0 then
        print(("[AutoChessMode] ℹ️ 玩家 " .. tostring(playerId)) .. " 没有存档数据，背包为空")
        playerState.benchPieces = {}
        inventoryHandler:sendInventoryData(playerId)
        return
    end
    local fullPieces = {}
    for ____, data in ipairs(loadedPieces) do
        local fullPiece = self.chessPieceDatabase:get(data.id)
        if fullPiece then
            fullPieces[#fullPieces + 1] = __TS__ObjectAssign({}, fullPiece, {health = data.health})
        else
            print(("[AutoChessMode] ⚠️ 存档中的棋子ID " .. data.id) .. " 在数据库中不存在")
        end
    end
    local selectedPieces = {}
    local remainingPieces = {unpack(fullPieces)}
    local actualCount = math.min(count, #fullPieces)
    if actualCount >= #fullPieces then
        __TS__ArrayPushArray(selectedPieces, fullPieces)
        __TS__ArraySetLength(remainingPieces, 0)
        print(((((("[AutoChessMode] 📦 玩家 " .. tostring(playerId)) .. " 背包棋子不足") .. tostring(count)) .. "个，全部消耗（") .. tostring(#fullPieces)) .. " 个）")
    else
        do
            local i = 0
            while i < actualCount do
                local randomIndex = math.floor(math.random() * #remainingPieces)
                local selectedPiece = remainingPieces[randomIndex + 1]
                selectedPieces[#selectedPieces + 1] = selectedPiece
                __TS__ArraySplice(remainingPieces, randomIndex, 1)
                i = i + 1
            end
        end
        print(((((("[AutoChessMode] 🎲 玩家 " .. tostring(playerId)) .. " 从背包随机抽取并消耗 ") .. tostring(actualCount)) .. " 个棋子，剩余 ") .. tostring(#remainingPieces)) .. " 个")
    end
    local remainingData = __TS__ArrayMap(
        remainingPieces,
        function(____, piece) return {
            id = piece.id,
            unitName = piece.unitName,
            displayName = piece.displayName,
            rarity = piece.rarity,
            cost = piece.cost,
            health = piece.health,
            maxHealth = piece.health,
            damage = piece.damage,
            armor = piece.armor,
            attackRange = piece.attackRange
        } end
    )
